import{g as a}from"./vendor-gsap-Bvc7XDwK.js";import{d as e,x as i,o,c,e as t,h as s,q as n,w as d,k as l,r,a as p,i as u}from"./vendor-vue-DxhJYBj6.js";import{_ as v}from"./index-C4hzqDL7.js";import"./vendor-BrHtBGhm.js";const m={class:"pagina-condiciones"},g={class:"header-condiciones"},A={class:"contenedor-estrecho header-content"},I={class:"contenedor-estrecho"},y={class:"navegacion-inferior"},E=v(e({__name:"CondicionesUsoAdiView",setup(e){i({title:"Condiciones de Uso A.D.I | SAO6",meta:[{name:"description",content:"Política de Tratamiento de Datos Personales de la Aplicación A.D.I (Automatización Digital Inteligente) de SISTEMA ALIMENTADOR ORIENTAL S.A.S."},{name:"keywords",content:"condiciones de uso, A.D.I, tratamiento de datos personales, SAO6, seguridad de la informacion, Medellín"},{name:"author",content:"SISTEMA ALIMENTADOR ORIENTAL S.A.S"},{name:"robots",content:"index, follow"},{property:"og:type",content:"article"},{property:"og:title",content:"Condiciones de Uso A.D.I | SAO6"},{property:"og:description",content:"Política de Tratamiento de Datos Personales de la Aplicación A.D.I (Automatización Digital Inteligente)."},{property:"og:url",content:"https://sao6.com.co/condiciones-de-uso-de-adi"},{property:"og:site_name",content:"SAO6 - Sistema Alimentador Oriental"}],link:[{rel:"canonical",href:"https://sao6.com.co/condiciones-de-uso-de-adi"}]});const v=l(null),E=l(null);return o(()=>{a.timeline().from(v.value,{y:30,opacity:0,duration:.8,ease:"power3.out"}).from(E.value,{y:20,opacity:0,duration:.8,ease:"power3.out"},"-=0.4")}),(a,e)=>{const i=r("router-link");return p(),c("div",m,[t("header",g,[t("div",A,[e[0]||(e[0]=t("div",{class:"categoria-tag"},"Legal",-1)),t("h1",{ref_key:"tituloRef",ref:v},"POLÍTICA DE TRATAMIENTO DE DATOS PERSONALES",512),e[1]||(e[1]=t("p",{class:"subtitle"},"APLICACIÓN A.D.I (Automatización Digital Inteligente)",-1))])]),t("article",{class:"contenido-condiciones",ref_key:"contenidoRef",ref:E},[t("div",I,[e[3]||(e[3]=s('<div class="cuerpo-texto" data-v-1830a3cc><section class="seccion-legal" data-v-1830a3cc><h2 data-v-1830a3cc>1. IDENTIFICACIÓN DEL RESPONSABLE DEL TRATAMIENTO</h2><p data-v-1830a3cc> SISTEMA ALIMENTADOR ORIENTAL S.A.S, sociedad comercial identificada con NIT 900566324-5, domiciliada en Medellín, en adelante el RESPONSABLE, actúa como responsable del tratamiento de los datos personales recopilados a través de la aplicación A.D.I (Automatización Digital Inteligente), en estricto cumplimiento de la Constitución Política de Colombia, la Ley 1581 de 2012, el Decreto Reglamentario 1377 de 2013 y demás normatividad aplicable. </p></section><section class="seccion-legal" data-v-1830a3cc><h2 data-v-1830a3cc>2. DESCRIPCIÓN DE LA APLICACIÓN A.D.I</h2><p data-v-1830a3cc> La aplicación A.D.I (Automatización Digital Inteligente) es una herramienta tecnológica de propiedad de SISTEMA ALIMENTADOR ORIENTAL S.A.S, diseñada para operar en dispositivos móviles para los colaboradores. Sus principales funcionalidades que implican el tratamiento de datos personales son: </p><ol data-v-1830a3cc><li data-v-1830a3cc><strong data-v-1830a3cc>Seguimiento de ubicación en segundo plano:</strong> la aplicación accede y registra en tiempo real la posición geográfica del dispositivo del usuario, incluso cuando la aplicación no está activa en primer plano.</li><li data-v-1830a3cc><strong data-v-1830a3cc>Grabación y almacenamiento de audio y voz:</strong> la aplicación puede acceder al micrófono del dispositivo para capturar, procesar y almacenar grabaciones de voz o audio del usuario.</li><li data-v-1830a3cc><strong data-v-1830a3cc>Recopilación y almacenamiento de datos personales:</strong> la aplicación almacena información personal del usuario para el cumplimiento de sus funcionalidades operativas y de gestión.</li></ol></section><section class="seccion-legal" data-v-1830a3cc><h2 data-v-1830a3cc>3. DATOS PERSONALES OBJETO DE TRATAMIENTO</h2><h3 data-v-1830a3cc>3.1. Datos personales de identificación general</h3><ul data-v-1830a3cc><li data-v-1830a3cc>Nombres y apellidos completos.</li><li data-v-1830a3cc>Número de documento de identidad (cédula de ciudadanía, NIT, pasaporte u otro).</li><li data-v-1830a3cc>Dirección de correo electrónico.</li><li data-v-1830a3cc>Número de teléfono o celular.</li><li data-v-1830a3cc>Cargo o función dentro de la organización.</li></ul><h3 data-v-1830a3cc>3.1. Datos de ubicación geográfica (dato sensible asimilado)</h3><p data-v-1830a3cc> La aplicación A.D.I recopila y almacena coordenadas GPS, puntos de recorrido, historial de trayectos y posición en tiempo real del dispositivo del usuario, incluso cuando la aplicación opera en segundo plano. Dada la naturaleza de este dato, su recolección requiere autorización previa, expresa e informada del Titular. </p><h3 data-v-1830a3cc>4.3. Datos de audio y voz (dato sensible)</h3><p data-v-1830a3cc> La aplicación accede al micrófono del dispositivo para capturar grabaciones de voz, instrucciones de voz y registros de audio asociados a la actividad laboral del usuario si es necesaria. Estos datos son considerados datos sensibles en la medida en que revelan características de la persona y se someten a las protecciones reforzadas previstas en el artículo 6 de la Ley 1581 de 2012. </p><h3 data-v-1830a3cc>3.4. Datos técnicos del dispositivo</h3><ul data-v-1830a3cc><li data-v-1830a3cc>Identificador único del dispositivo (ID de dispositivo, IMEI u otros identificadores).</li><li data-v-1830a3cc>Sistema operativo y versión de la aplicación.</li><li data-v-1830a3cc>Registros de actividad e interacción con la aplicación.</li><li data-v-1830a3cc>Dirección IP de la conexión.</li></ul></section><section class="seccion-legal" data-v-1830a3cc><h2 data-v-1830a3cc>4. DATOS SENSIBLES Y PROTECCIÓN ESPECIAL</h2><p data-v-1830a3cc> De conformidad con el artículo 5 de la Ley 1581 de 2012, se consideran datos sensibles aquellos que afectan la intimidad del Titular o cuyo uso indebido puede generar discriminación. En el marco de la aplicación A.D.I, se tratan los siguientes datos sensibles: </p><p data-v-1830a3cc><strong data-v-1830a3cc>Grabaciones de audio y voz:</strong> revelan características personales, contexto y contenido de conversaciones del Titular, por lo que requieren autorización expresa e independiente del Titular. </p><p data-v-1830a3cc><strong data-v-1830a3cc>Datos de ubicación en tiempo real y en segundo plano:</strong> la trazabilidad permanente de la posición geográfica constituye información altamente sensible que puede revelar patrones de conducta, lugares de residencia, trabajo, reunión o hábitos privados del Titular. </p><p data-v-1830a3cc> El suministro de este tipo de datos es de carácter facultativo; sin embargo, la negativa a otorgar autorización para su tratamiento puede limitar o impedir el funcionamiento de determinadas funcionalidades de la aplicación A.D.I. </p></section><section class="seccion-legal" data-v-1830a3cc><h2 data-v-1830a3cc>5. FINALIDADES DEL TRATAMIENTO</h2><h3 data-v-1830a3cc>5.1. Finalidades relacionadas con la ubicación en tiempo real</h3><ol data-v-1830a3cc><li data-v-1830a3cc>Seguimiento y monitoreo operativo de actividades, rutas o desplazamientos asociados a los procesos internos de SISTEMA ALIMENTADOR ORIENTAL S.A.S.</li><li data-v-1830a3cc>Verificación de presencia, asistencia o cumplimiento de actividades en campo.</li><li data-v-1830a3cc>Generación de reportes de trayectoria, eficiencia y desempeño operativo.</li><li data-v-1830a3cc>Gestión de la seguridad del personal en campo y respuesta ante emergencias o incidentes.</li></ol><h3 data-v-1830a3cc>5.2. Finalidades relacionadas con el audio y voz</h3><ol data-v-1830a3cc><li data-v-1830a3cc>Registro de instrucciones, reportes verbales o comunicaciones operativas del usuario dentro de la aplicación.</li><li data-v-1830a3cc>Digitalización y procesamiento de contenido de voz para la automatización de tareas y flujos de trabajo.</li><li data-v-1830a3cc>Auditoría, control de calidad y verificación de comunicaciones operativas cuando la normativa interna lo requiera.</li></ol><h3 data-v-1830a3cc>5.3. Finalidades relacionadas con datos personales generales</h3><ol data-v-1830a3cc><li data-v-1830a3cc>Identificación y autenticación del usuario dentro de la aplicación.</li><li data-v-1830a3cc>Cumplimiento de obligaciones legales, contractuales y laborales del RESPONSABLE.</li><li data-v-1830a3cc>Administración de la relación contractual entre el RESPONSABLE y el Titular.</li><li data-v-1830a3cc>Envío de comunicaciones operativas, notificaciones institucionales e información relevante para el uso de la aplicación.</li><li data-v-1830a3cc>Evaluación de la calidad del servicio y mejoramiento continuo de las funcionalidades de la aplicación.</li><li data-v-1830a3cc>Atención y trámite de requerimientos, quejas y reclamos presentados por el Titular.</li></ol></section><section class="seccion-legal" data-v-1830a3cc><h2 data-v-1830a3cc>6. DERECHOS DEL TITULAR</h2><p data-v-1830a3cc> En virtud del artículo 8 de la Ley 1581 de 2012, el Titular de los datos personales tratados por la aplicación A.D.I tiene los siguientes derechos, los cuales podrá ejercer en cualquier momento: </p><ul data-v-1830a3cc><li data-v-1830a3cc>Acceder gratuitamente a sus datos personales que sean objeto de tratamiento.</li><li data-v-1830a3cc>Conocer, actualizar y rectificar sus datos personales cuando sean inexactos, incompletos, fraccionados, que induzcan a error, o cuyo tratamiento esté expresamente prohibido o no haya sido autorizado.</li><li data-v-1830a3cc>Solicitar prueba de la autorización otorgada al RESPONSABLE, salvo cuando expresamente se exceptúe como requisito para el tratamiento.</li><li data-v-1830a3cc>Ser informado por el RESPONSABLE sobre el uso que se ha dado a sus datos personales, previa solicitud.</li><li data-v-1830a3cc>Revocar la autorización y/o solicitar la supresión de los datos cuando en el tratamiento no se respeten los principios, derechos y garantías constitucionales y legales vigentes, o cuando no exista obligación legal o contractual que imponga el mantenimiento del dato.</li><li data-v-1830a3cc>Abstenerse de responder preguntas sobre datos sensibles o datos de niños, niñas y adolescentes.</li></ul></section><section class="seccion-legal" data-v-1830a3cc><h2 data-v-1830a3cc>7. AUTORIZACIÓN DEL TITULAR</h2><p data-v-1830a3cc> De conformidad con los artículos 9 y 10 de la Ley 1581 de 2012 y el artículo 7 del Decreto 1377 de 2013, el tratamiento de datos personales requiere la autorización previa, expresa e informada del Titular. En el caso de la aplicación A.D.I, dicha autorización se obtiene a través del mecanismo de aceptación explícita dispuesto durante el proceso de instalación y/o primer uso de la aplicación, así como mediante la aceptación de los permisos requeridos en el dispositivo para el acceso a: </p><ul data-v-1830a3cc><li data-v-1830a3cc>Ubicación del dispositivo.</li><li data-v-1830a3cc>Micrófono del dispositivo para grabación de audio y voz.</li><li data-v-1830a3cc>Almacenamiento local del dispositivo.</li></ul><p data-v-1830a3cc> Para los datos sensibles (audio, voz y ubicación en segundo plano), se solicitará una autorización específica, diferenciada e independiente del Titular. </p></section><section class="seccion-legal" data-v-1830a3cc><h2 data-v-1830a3cc>8. MEDIDAS DE SEGURIDAD</h2><p data-v-1830a3cc> SISTEMA ALIMENTADOR ORIENTAL S.A.S implementa las medidas técnicas, humanas y administrativas necesarias para garantizar la seguridad de los datos personales tratados a través de la aplicación A.D.I, en cumplimiento del artículo 17, literal (f) de la Ley 1581 de 2012. Entre las medidas adoptadas se incluyen: </p><ul data-v-1830a3cc><li data-v-1830a3cc>Control de acceso basado en roles y autenticación segura para el acceso a los sistemas de información.</li><li data-v-1830a3cc>Registro y auditoría de accesos y operaciones sobre los datos personales.</li><li data-v-1830a3cc>Políticas internas de gestión de incidentes de seguridad de la información y brechas de datos.</li><li data-v-1830a3cc>Capacitación periódica del personal que tiene acceso a datos personales.</li><li data-v-1830a3cc>Suscripción de acuerdos de confidencialidad con proveedores y terceros encargados del tratamiento.</li></ul></section><section class="seccion-legal" data-v-1830a3cc><h2 data-v-1830a3cc>9. TIEMPO DE CONSERVACIÓN DE LOS DATOS</h2><p data-v-1830a3cc> Los datos personales serán conservados durante el tiempo necesario para cumplir con las finalidades que motivaron su recolección, y mientras subsista la relación contractual o legal con el Titular. Una vez cumplida la finalidad y superados los plazos legales, los datos serán suprimidos, anonimizados o bloqueados de forma segura. </p><p data-v-1830a3cc><strong data-v-1830a3cc>Especificidades por tipo de dato:</strong></p><ul data-v-1830a3cc><li data-v-1830a3cc><strong data-v-1830a3cc>Datos de ubicación (registros de trayecto):</strong> conservados por el tiempo necesario para las finalidades operativas declaradas y conforme a los plazos legales aplicables.</li><li data-v-1830a3cc><strong data-v-1830a3cc>Grabaciones de audio y voz:</strong> conservadas por el período mínimo necesario para las finalidades declaradas; una vez cumplida la finalidad, serán eliminadas de forma segura.</li><li data-v-1830a3cc><strong data-v-1830a3cc>Datos personales de identificación:</strong> conservados mientras dure la relación contractual o laboral y por los plazos adicionales exigidos por la normativa laboral, tributaria y contable colombiana.</li></ul></section><section class="seccion-legal" data-v-1830a3cc><h2 data-v-1830a3cc>10. AUTORIDAD DE CONTROL</h2><p data-v-1830a3cc> La autoridad encargada de velar por el cumplimiento de la Ley 1581 de 2012 es la Superintendencia de Industria y Comercio (SIC), ante la cual el Titular podrá presentar quejas una vez agotado el procedimiento ante el RESPONSABLE. </p><ul data-v-1830a3cc><li data-v-1830a3cc><strong data-v-1830a3cc>Sitio web:</strong> www.sic.gov.co</li><li data-v-1830a3cc><strong data-v-1830a3cc>Dirección:</strong> Carrera 13 No. 27 – 00, Bogotá D.C., Colombia.</li><li data-v-1830a3cc><strong data-v-1830a3cc>Línea de atención:</strong> 601 587 0000</li></ul></section><footer class="firma-legal" data-v-1830a3cc><p data-v-1830a3cc><strong data-v-1830a3cc>SISTEMA ALIMENTADOR ORIENTAL S.A.S — NIT 900566324-5</strong></p><p data-v-1830a3cc>Responsable del Tratamiento de Datos Personales – Aplicación A.D.I</p></footer></div>',1)),t("div",y,[n(i,{to:"/",class:"btn-volver"},{default:d(()=>[...e[2]||(e[2]=[t("svg",{width:"20",height:"20",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"2"},[t("path",{d:"M19 12H5M12 19l-7-7 7-7"})],-1),u(" Volver al Inicio ",-1)])]),_:1})])])],512)])}}}),[["__scopeId","data-v-1830a3cc"]]);export{E as default};
